import { describe, expect, it } from 'vitest';
import { NativePdfReader } from '../../src/pdf/native-reader.js';
import { createTrueTypeGlyphReader } from '../../src/pdf/ttf-outline.js';
import { readTrueTypeMetrics } from '../../src/pdf/font-metrics.js';
import { loadAsset, options, simplePdf } from './fixtures.js';

// Original four-table sfnt fixtures isolate the glyf short-vector sign flags.
// They are outline-ABI inputs, not complete installable browser fonts.
const shortDeltas = [
  ["negative-x",
    "",
    [[0,0],[100,0],[0,100]]],
  ["negative-y",
    "",
    [[0,0],[100,100],[200,0]]],
  ["negative-both",
    "",
    [[100,100],[0,0],[100,0]]],
  ["repeat-negative-x",
    "",
    [[100,0],[-100,0],[-300,0]]],
  ["repeat-negative-y",
    "",
    [[0,100],[0,-100],[0,-300]]],
  ["repeat-negative-both",
    "",
    [[100,100],[-100,-100],[-300,-300]]],
  ["repeat-positive-control",
    "",
    [[0,0],[100,50],[200,100]]],
  ["full-unsigned-byte-magnitude",
    "",
    [[255,255],[0,0],[255,0]]],
];

describe('original native TrueType outlines', () => {
  it.each(shortDeltas)('preserves short coordinate deltas: %s', async (_name, hex, vertices) => {
    const reader = await NativePdfReader.create(simplePdf(''), options);
    try {
      const bytes = new Uint8Array(Buffer.from(hex, 'hex'));
      const glyph = createTrueTypeGlyphReader(reader, bytes, { units: 1000, glyphCount: 1 })(0);
      expect(glyph).toEqual({
        outline: [...vertices.map((points, i) => ({ op: i ? 2 : 1, points })), { op: 4, points: [] }],
        fontMatrix: [.001, 0, 0, .001, 0, 0],
      });
    } finally { reader.destroy(); }
  });

  it('outlines the retained Liberation Sans A with both contours and its original font units', async () => {
    const bytes = await loadAsset('standard_fonts/LiberationSans-Regular.ttf');
    const metrics = readTrueTypeMetrics(bytes), reader = await NativePdfReader.create(simplePdf(''), options);
    try {
      const glyph = createTrueTypeGlyphReader(reader, bytes, metrics)(metrics.glyphId(65));
      expect(metrics.glyphId(65)).toBe(36);
      expect(glyph.fontMatrix).toEqual([1 / 2048, 0, 0, 1 / 2048, 0, 0]);
      expect(glyph.outline).toHaveLength(21);
      expect(glyph.outline.slice(0, 9)).toEqual([
        { op: 1, points: [1167, 0] },
        { op: 2, points: [1006, 412] },
        { op: 2, points: [364, 412] },
        { op: 2, points: [202, 0] },
        { op: 2, points: [4, 0] },
        { op: 2, points: [579, 1409] },
        { op: 2, points: [796, 1409] },
        { op: 2, points: [1362, 0] },
        { op: 4, points: [] },
      ]);
      expect(glyph.outline.filter(segment => segment.op === 3)).toHaveLength(8);
      expect(glyph.outline.filter(segment => segment.op === 4)).toHaveLength(2);
    } finally { reader.destroy(); }
  });
});
